const body = $json.body ?? $json;
if (!body.topic || typeof body.topic !== 'string') throw new Error('topic is required');
return [{ json: { schema_version: '1.0', request_id: body.request_id ?? ('n8n-' + Date.now()), topic: body.topic.trim(), interest_context: Array.isArray(body.interest_context) ? body.interest_context.slice(0, 12) : [], sources: Array.isArray(body.sources) && body.sources.length ? body.sources : ['youtube'], depth: ['quick','standard','deep'].includes(body.depth) ? body.depth : 'standard', days: Number.isInteger(body.days) ? Math.min(365, Math.max(1, body.days)) : 30, max_results: Number.isInteger(body.max_results) ? Math.min(200, Math.max(1, body.max_results)) : 25, plan: body.plan && typeof body.plan === 'object' ? body.plan : undefined } }];

const envelope = $json;
if (!envelope.ok) throw new Error(envelope.error?.message ?? 'research failed');
const result = envelope.result ?? {};
const ranked = [...(result.results ?? [])].sort((a,b) => (b.curator_score ?? b.relevance_score ?? 0) - (a.curator_score ?? a.relevance_score ?? 0));
return [{ json: { request_id: envelope.request_id, schema_version: result.schema_version, query: result.query, generated_at: result.generated_at, recommendations: ranked.slice(0,5).map((x,i) => ({ rank: i+1, title: x.title, url: x.url, source: x.source, published_at: x.published_at, curator_score: x.curator_score, topic_relevance_score: x.topic_relevance_score, topic_anchor_score: x.topic_anchor_score, personal_relevance_score: x.personal_relevance_score, recommendation_reason: x.recommendation_reason, summary: x.summary })) } }];
